import { GoogleGenAI, Type, FunctionDeclaration, Schema } from "@google/genai";
import { AssessmentQuestion, ChatMessage, AnalysisResult } from "../types";

// Note: We instantiate the client inside functions to ensure we pick up the latest 
// process.env.API_KEY after the user selects it in the UI.

const modelId = "gemini-3-pro-preview";

// --- Helper: Output Sanitization ---
// This is a safety net to catch "hallucinations" where the model refers to diagrams it didn't generate.
const sanitizeHallucinations = (text: string): string => {
  if (!text) return text;
  let clean = text;

  // Regex patterns to catch common diagram references
  const patterns = [
    /as (shown|seen|depicted|illustrated) in the (diagram|image|figure|picture)( above| below| here)?/gi,
    /refer to the (diagram|image|figure|picture)( above| below| here)?/gi,
    /the (diagram|image|figure|picture) (above|below|here) shows/gi,
    /(see|look at) the (diagram|image|figure|picture)/gi,
    /in the (diagram|image|figure|picture) (above|below)/gi,
    /\(see (figure|diagram) \d+\)/gi
  ];

  patterns.forEach(regex => {
    // Replace with neutral referencing
    clean = clean.replace(regex, "as described");
  });

  // Cleanup grammar if replacement caused awkward phrasing
  clean = clean
    .replace("as described shows", "the description shows")
    .replace("as described, shows", "the description shows");

  return clean;
};

// --- 1. Assessment Generation ---

export const generateAssessment = async (topic: string, base64Image?: string): Promise<AssessmentQuestion[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `
    The user wants to learn about: "${topic}".
    ${base64Image ? "They have also provided an image context." : ""}
    Create a diagnostic quiz to assess the student's current knowledge level.
    Generate exactly 5 multiple-choice questions.
    The questions must be in strictly increasing order of difficulty:
    1. Very Basic/Fundamental
    2. Beginner
    3. Intermediate
    4. Advanced
    5. Expert/Complex Application

    Return the response as a JSON array.
  `;

  const schema: Schema = {
    type: Type.ARRAY,
    items: {
      type: Type.OBJECT,
      properties: {
        id: { type: Type.INTEGER },
        question: { type: Type.STRING },
        options: {
          type: Type.ARRAY,
          items: { type: Type.STRING },
          description: "4 distinct options"
        },
        correctIndex: { type: Type.INTEGER, description: "Index of the correct option (0-3)" },
        difficulty: { type: Type.INTEGER, description: "Difficulty level 1-5" },
      },
      required: ["id", "question", "options", "correctIndex", "difficulty"],
    },
  };

  const parts: any[] = [{ text: prompt }];
  if (base64Image) {
    parts.push({
      inlineData: {
        mimeType: "image/jpeg", 
        data: base64Image,
      },
    });
  }

  try {
    const response = await ai.models.generateContent({
      model: modelId,
      contents: { parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: schema,
        systemInstruction: "You are an expert examiner. Create precise, clear, and pedagogically sound questions.",
      },
    });

    if (response.text) {
      const rawQuestions = JSON.parse(response.text) as AssessmentQuestion[];
      // Append "I don't know" option to every question
      return rawQuestions.map(q => ({
        ...q,
        options: [...q.options, "I don't know"]
      }));
    }
    throw new Error("No data returned from Gemini");
  } catch (error) {
    console.error("Error generating assessment:", error);
    throw error;
  }
};

// --- 2. Initial Conversation & Assessment Trigger ---

const startAssessmentFunction: FunctionDeclaration = {
  name: 'startAssessment',
  description: 'Starts the assessment diagnostic when the user has provided a clear, valid topic they want to learn.',
  parameters: {
    type: Type.OBJECT,
    properties: {
      topic: {
        type: Type.STRING,
        description: 'The specific topic the user wants to learn.',
      },
    },
    required: ['topic'],
  },
};

export const processInitialMessage = async (
  history: ChatMessage[],
  currentText: string,
  currentImage?: string
): Promise<{ text: string, toolCall?: { name: string, args: any } }> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const formattedHistory = history
    .filter(h => h.role === 'model' || h.role === 'user')
    .map(h => {
       const parts: any[] = [];
       if (h.content && h.content.trim()) {
         parts.push({ text: h.content });
       }
       if (h.image && h.role === 'user') {
         parts.push({ inlineData: { mimeType: 'image/jpeg', data: h.image } });
       }
       return { role: h.role, parts };
    });

  const currentParts: any[] = [];
  if (currentText && currentText.trim()) {
    currentParts.push({ text: currentText });
  }
  if (currentImage) {
    currentParts.push({ inlineData: { mimeType: 'image/jpeg', data: currentImage } });
  }

  if (currentParts.length === 0) {
    return { text: "Please provide some text or an image." };
  }

  const systemInstruction = `
    You are a friendly, helpful AI Tutor.

    Your Goal: Determine if the user has provided a topic they want to learn so you can assess them.

    1. IF the user input is a valid topic (e.g., "I want to learn physics", "Teach me about reaction diffusion", "Help me with this image"):
       - You MUST reply to the user textually first. In your text reply, enthusiastically acknowledge the topic and EXPLAIN that you need to ask a short 5-question quiz to understand their current level so you can customize the teaching.
       - AND simultaneously CALL the 'startAssessment' function with the identified topic.

    2. IF the user input is ambiguous, unclear, gibberish, or just a greeting (e.g., "hello", "hi", "asdf"):
       - Do NOT call the function.
       - Conversationally ask them what they would like to learn today.

    3. Always be polite and encouraging.
  `;

  try {
    const chat = ai.chats.create({
      model: modelId,
      history: formattedHistory,
      config: {
        systemInstruction,
        tools: [{ functionDeclarations: [startAssessmentFunction] }],
      },
    });

    const result = await chat.sendMessage({ message: currentParts });
    const calls = result.functionCalls;

    // Check for tool call
    if (calls && calls.length > 0) {
      const call = calls[0];
      return {
        // If the model followed instructions, result.text contains the explanation "Sure, I can help with X. First let me ask..."
        // If it's empty for some reason, we fallback to a default explanation.
        text: result.text || "That sounds like a great topic! To help me teach you effectively, I'll need to ask a few quick questions to gauge your current understanding. Let's get started.",
        toolCall: {
          name: call.name,
          args: call.args
        }
      };
    }

    // Default conversational response
    return { text: result.text || "I didn't catch that. Could you please specify a topic?" };

  } catch (error) {
    console.error("Initial processing error:", error);
    return { text: "I'm having trouble connecting. Please try again." };
  }
};

// --- 3. Analysis ---

export const analyzeStudentLevel = async (
  topic: string,
  questions: AssessmentQuestion[],
  answers: number[]
): Promise<AnalysisResult> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const quizSummary = questions.map((q, i) => ({
    question: q.question,
    difficulty: q.difficulty,
    userAnswer: q.options[answers[i]],
    isCorrect: answers[i] === q.correctIndex
  }));

  const prompt = `
    Topic: ${topic}
    Analyze the following quiz results:
    ${JSON.stringify(quizSummary, null, 2)}

    Note: If the "userAnswer" is "I don't know", it indicates a knowledge gap in that area.

    Determine the student's proficiency level.
    Provide a summary and a recommended teaching path.
  `;

  const schema: Schema = {
    type: Type.OBJECT,
    properties: {
      level: { type: Type.STRING, description: "e.g., Novice, Intermediate, Proficient" },
      summary: { type: Type.STRING, description: "Brief assessment of strengths and weaknesses" },
      recommendedPath: { type: Type.STRING, description: "How you plan to teach them moving forward" }
    },
    required: ["level", "summary", "recommendedPath"]
  };

  const response = await ai.models.generateContent({
    model: modelId,
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: schema
    }
  });

  if (response.text) {
    return JSON.parse(response.text) as AnalysisResult;
  }
  throw new Error("Failed to analyze results");
};

// --- 4. Chat & Diagram Generation ---

const generateDiagramFunction: FunctionDeclaration = {
  name: 'generateDiagram',
  description: 'Generates a visual diagram or illustration to explain a concept better.',
  parameters: {
    type: Type.OBJECT,
    properties: {
      prompt: {
        type: Type.STRING,
        description: 'A detailed description of the image/diagram to generate.',
      },
    },
    required: ['prompt'],
  },
};

export const generateImage = async (prompt: string): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-image-preview',
      contents: {
        parts: [{ text: prompt }]
      },
      config: {
          imageConfig: { aspectRatio: "16:9" }
      }
    });

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return part.inlineData.data;
      }
    }
    throw new Error("No image generated");
  } catch (e) {
    console.error("Image gen failed", e);
    throw e;
  }
};

export const sendChatMessage = async (
  history: ChatMessage[],
  newMessageText: string,
  newMessageImage: string | undefined,
  userLevel: string,
  topic: string,
  onImageGenerated: (base64: string) => void,
  systemInjection?: string // Optional extra instruction (e.g., for starting the session)
): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const formattedHistory = history
    .filter(h => h.role === 'model' || h.role === 'user')
    .map(h => {
      const parts: any[] = [];
      if (h.content && h.content.trim()) {
        parts.push({ text: h.content });
      }
      if (h.image && h.role === 'user') {
        parts.push({ inlineData: { mimeType: 'image/jpeg', data: h.image } });
      }
      return {
        role: h.role,
        parts
      };
    });

  // Since chat.sendMessage appends the new message, we should not include it in history init if we are calling sendMessage with it.
  const historyForChat = formattedHistory.slice(0, -1);

  let systemInstruction = `
    You are an expert tutor teaching: "${topic}".
    The student is at level: "${userLevel}".

    STRATEGY:
    1. Start from their current level.
    2. Use the Socratic method (ask guiding questions).
    3. Break down complex concepts into simple steps.

    VISUALIZATION & OUTPUT RULES:
    1. **Primary Diagram Source (Code)**: For all math, physics, and logic structure, you MUST use LaTeX Block Math ($$ ... $$) or Markdown Tables. 
       - Refer to these as "the equation", "the derivation", "the table", or "the structure below".
       - NEVER refer to them as "the diagram" or "the image".

    2. **Secondary Diagram Source (Image)**: Use the 'generateDiagram' tool ONLY for spatial/organic concepts (cells, complex physics setups).
       - If you trigger the tool, you MAY say "As shown in the diagram...".
       - If you DO NOT trigger the tool (or if it fails), you MUST NOT use words like "diagram", "figure", "image", "shown above". 
       - Instead, describe it visually using text: "Imagine a triangle...", "Consider a structure where..."

    3. **Correction Protocol**: If image generation fails, immediate switch to text/LaTeX explanation without mentioning the failure to the user.
  `;

  if (systemInjection) {
    systemInstruction += `\n\nIMPORTANT CONTEXT UPDATE: ${systemInjection}`;
  }

  try {
    const chat = ai.chats.create({
      model: modelId,
      history: historyForChat,
      config: {
        systemInstruction,
        tools: [{ functionDeclarations: [generateDiagramFunction] }],
      },
    });

    // Prepare current message parts
    const currentParts: any[] = [];
    if (newMessageText && newMessageText.trim()) {
      currentParts.push({ text: newMessageText });
    }
    if (newMessageImage) {
      currentParts.push({ inlineData: { mimeType: 'image/jpeg', data: newMessageImage } });
    }

    const result = await chat.sendMessage({ message: currentParts });
    const calls = result.functionCalls;
    let imageWasGenerated = false;

    if (calls && calls.length > 0) {
      const call = calls[0];
      if (call.name === 'generateDiagram') {
        const args = call.args as { prompt: string };
        const diagramPrompt = `Diagram for educational purposes: ${args.prompt}. Clear, labelled, schematic style.`;

        try {
          const imageBase64 = await generateImage(diagramPrompt);
          onImageGenerated(imageBase64);
          imageWasGenerated = true;

          // Send success response to model
          const functionResponse = await chat.sendMessage({
            message: [{
              functionResponse: {
                name: 'generateDiagram',
                response: { result: 'Image generated successfully and displayed.' }
              }
            }]
          });

          return functionResponse.text || "Here is the diagram to help explain.";

        } catch (imgError) {
          console.error("Image generation tool failed:", imgError);
          // Graceful fallback: Tell the model the tool failed and FORCE it to rewrite without referencing the image.
          const errorResponse = await chat.sendMessage({
             message: [{
              functionResponse: {
                name: 'generateDiagram',
                response: { result: 'SYSTEM ERROR: Image generation failed. REWRITE your explanation using ONLY text and LaTeX ($$). Do NOT refer to any image or diagram.' }
              }
            }]
          });
          // We still sanitize this just in case the model is stubborn
          return sanitizeHallucinations(errorResponse.text || "I can explain this using equations.");
        }
      }
    }

    // If no image was generated, run the safety net to remove "hallucinated" references
    const finalText = result.text || "";
    return imageWasGenerated ? finalText : sanitizeHallucinations(finalText);

  } catch (error) {
    console.error("Chat error:", error);
    return "I apologize, but I encountered an error processing your request.";
  }
};

import React, { useState, useEffect, useRef } from 'react';
import ReactMarkdown from 'react-markdown';
import remarkMath from 'remark-math';
import rehypeKatex from 'rehype-katex';
import remarkGfm from 'remark-gfm';
import { ChatMessage, AppState } from '../types';

interface Props {
  messages: ChatMessage[];
  onSendMessage: (text: string, image?: string) => void;
  onOptionSelect: (questionId: number, optionIndex: number) => void;
  isTyping: boolean;
  appState: AppState;
}

const ChatView: React.FC<Props> = ({ messages, onSendMessage, onOptionSelect, isTyping, appState }) => {
  const [input, setInput] = useState('');
  const [selectedImage, setSelectedImage] = useState<string | undefined>(undefined);
  const [isDragging, setIsDragging] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isTyping]);

  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = `${Math.min(textareaRef.current.scrollHeight, 150)}px`;
    }
  }, [input]);

  const processFile = (file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const base64 = reader.result as string;
      const base64Data = base64.split(',')[1];
      setSelectedImage(base64Data);
    };
    reader.readAsDataURL(file);
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      processFile(file);
    }
  };

  const handlePaste = (e: React.ClipboardEvent) => {
    const items = e.clipboardData.items;
    for (let i = 0; i < items.length; i++) {
      if (items[i].type.indexOf('image') !== -1) {
        const file = items[i].getAsFile();
        if (file) {
          processFile(file);
          e.preventDefault(); // Prevent pasting the binary string into textarea
        }
      }
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    const file = e.dataTransfer.files[0];
    if (file && file.type.startsWith('image/')) {
      processFile(file);
    }
  };

  const submitMessage = () => {
    if ((input.trim() || selectedImage) && !isTyping) {
      onSendMessage(input, selectedImage);
      setInput('');
      setSelectedImage(undefined);
      if (textareaRef.current) {
        textareaRef.current.style.height = 'auto';
      }
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      submitMessage();
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    submitMessage();
  };

  // Helper to render assessment questions
  const renderAssessmentBubble = (msg: ChatMessage) => {
    const { assessmentData } = msg;
    if (!assessmentData) return null;

    return (
      <div className="bg-white border border-gray-200 rounded-2xl rounded-bl-none p-5 shadow-sm w-full max-w-lg">
        <div className="flex items-center justify-between mb-4">
          <span className="text-xs font-bold text-primary tracking-wider uppercase">Assessment Question</span>
          <span className={`text-xs px-2 py-1 rounded-full ${
            assessmentData.question.difficulty <= 2 ? 'bg-green-100 text-green-800' :
            assessmentData.question.difficulty <= 4 ? 'bg-yellow-100 text-yellow-800' :
            'bg-red-100 text-red-800'
          }`}>
            Level {assessmentData.question.difficulty}
          </span>
        </div>

        <div className="text-gray-900 font-semibold text-lg mb-4 markdown-content">
          <ReactMarkdown 
            remarkPlugins={[remarkMath, remarkGfm]} 
            rehypePlugins={[rehypeKatex]}
          >
            {assessmentData.question.question}
          </ReactMarkdown>
        </div>

        <div className="space-y-2">
          {assessmentData.question.options.map((option, idx) => {
            const isSelected = assessmentData.selectedOptionIndex === idx;
            const isDisabled = assessmentData.isAnswered;

            let btnClass = "w-full text-left px-4 py-3 rounded-xl border transition-all duration-200 flex items-center ";
            if (isSelected) {
              btnClass += "bg-primary border-primary text-white shadow-md";
            } else if (isDisabled) {
              btnClass += "bg-gray-50 border-gray-200 text-gray-400 cursor-not-allowed";
            } else {
              btnClass += "bg-white border-gray-200 hover:border-primary hover:bg-indigo-50 text-gray-700 cursor-pointer";
            }

            return (
              <button
                key={idx}
                onClick={() => !isDisabled && onOptionSelect(assessmentData.question.id, idx)}
                disabled={isDisabled}
                className={btnClass}
              >
                <div className={`w-5 h-5 rounded-full border mr-3 flex items-center justify-center flex-shrink-0 ${
                  isSelected ? 'border-white' : 'border-gray-400'
                }`}>
                  {isSelected && <div className="w-2.5 h-2.5 rounded-full bg-white" />}
                </div>
                <div className="flex-1">
                   <ReactMarkdown 
                    remarkPlugins={[remarkMath, remarkGfm]} 
                    rehypePlugins={[rehypeKatex]}
                    components={{
                      p: ({node, ...props}) => <span {...props} />, // Render options as spans mostly
                    }}
                  >
                    {option}
                  </ReactMarkdown>
                </div>
              </button>
            );
          })}
        </div>
      </div>
    );
  };

  return (
    <div 
      className="flex flex-col h-screen bg-gray-50 font-sans relative overflow-hidden"
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
    >
      {/* Drag Overlay */}
      {isDragging && (
        <div className="absolute inset-0 z-50 bg-primary/10 backdrop-blur-sm border-4 border-primary border-dashed m-4 rounded-3xl flex items-center justify-center pointer-events-none">
          <div className="bg-white p-6 rounded-2xl shadow-xl flex flex-col items-center animate-bounce">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-12 w-12 text-primary mb-2" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
            </svg>
            <span className="text-lg font-bold text-primary">Drop image to upload</span>
          </div>
        </div>
      )}

      {/* Header */}
      <div className="bg-white/80 backdrop-blur-md sticky top-0 z-20 border-b border-gray-100 px-6 py-4">
        <div className="max-w-4xl mx-auto flex items-center space-x-3">
          <div className="bg-primary/10 p-2 rounded-lg">
             <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-primary" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" />
            </svg>
          </div>
          <div>
            <h1 className="text-lg font-bold text-gray-900">ProfAI</h1>
            <p className="text-xs text-gray-500">Adaptive Tutor • Gemini 3 Pro</p>
          </div>
        </div>
      </div>

      {/* Messages */}
      <div className="flex-1 overflow-y-auto min-h-0 p-4 sm:p-6 scrollbar-hide">
        <div className="max-w-3xl mx-auto space-y-6 pb-4">
          {messages.map((msg) => (
            <div
              key={msg.id}
              className={`flex w-full ${msg.role === 'user' ? 'justify-end' : 'justify-start'} animate-fade-in`}
            >
              {msg.role === 'model' && msg.type !== 'assessment' && (
                <div className="w-8 h-8 rounded-full bg-indigo-100 flex items-center justify-center mr-2 flex-shrink-0 mt-2">
                  <svg className="w-5 h-5 text-indigo-600" fill="currentColor" viewBox="0 0 20 20"><path d="M10 2a8 8 0 100 16 8 8 0 000-16zm0 14a6 6 0 110-12 6 6 0 010 12z"/></svg>
                </div>
              )}

              {msg.type === 'assessment' ? (
                renderAssessmentBubble(msg)
              ) : (
                <div
                  className={`max-w-[85%] sm:max-w-[75%] rounded-2xl p-4 shadow-sm text-sm sm:text-base leading-relaxed ${
                    msg.role === 'user'
                      ? 'bg-primary text-white rounded-br-none'
                      : 'bg-white text-gray-800 border border-gray-100 rounded-bl-none'
                  }`}
                >
                  {/* Image Content */}
                  {msg.image && (
                    <div className="mb-3 rounded-lg overflow-hidden border border-white/20">
                      <img 
                        src={`data:image/jpeg;base64,${msg.image}`} 
                        alt="Content"
                        className="max-h-64 w-auto object-cover"
                      />
                      {msg.isDiagram && (
                        <div className="bg-gray-100/90 backdrop-blur px-2 py-1 text-[10px] text-gray-500 font-medium uppercase tracking-wide">
                          AI Generated Diagram
                        </div>
                      )}
                    </div>
                  )}

                  {/* Markdown Text Content */}
                  <div className={`markdown-content ${msg.role === 'user' ? 'text-white' : 'text-gray-800'}`}>
                    <ReactMarkdown 
                      remarkPlugins={[remarkMath, remarkGfm]} 
                      rehypePlugins={[rehypeKatex]}
                      components={{
                        // Override link color for user vs bot
                        a: ({node, ...props}) => (
                          <a 
                            className={msg.role === 'user' ? "underline text-white" : "text-primary underline hover:text-indigo-700"} 
                            target="_blank" 
                            rel="noopener noreferrer" 
                            {...props} 
                          />
                        ),
                        // Ensure lists render correctly
                         ul: ({node, ...props}) => <ul className="list-disc pl-4 mb-2" {...props} />,
                         ol: ({node, ...props}) => <ol className="list-decimal pl-4 mb-2" {...props} />,
                         // Render code blocks cleanly
                         pre: ({node, ...props}) => (
                           <pre className={`p-2 rounded-lg overflow-x-auto my-2 ${msg.role === 'user' ? 'bg-indigo-700 text-white' : 'bg-gray-100 text-gray-800'}`} {...props} />
                         ),
                         // Add specific styling for block math to make it look like a diagram/panel
                         p: ({node, children, ...props}) => {
                            // Check if children contain math blocks (this is heuristic as react-markdown wraps katex in divs usually, but useful for spacing)
                            return <p className="mb-3 last:mb-0 leading-7" {...props}>{children}</p>;
                         },
                         code: ({node, className, ...props}) => {
                           const isInline = !className;
                           return (
                             <code 
                               className={`${isInline ? 'px-1 rounded bg-opacity-20 ' : ''} ${
                                 msg.role === 'user' 
                                   ? (isInline ? 'bg-white/20 text-white font-mono text-sm' : 'text-white font-mono text-sm') 
                                   : (isInline ? 'bg-gray-200 text-gray-800 font-mono text-sm' : 'text-gray-800 font-mono text-sm')
                               }`} 
                               {...props} 
                             />
                           );
                         }
                      }}
                    >
                      {msg.content}
                    </ReactMarkdown>
                  </div>
                </div>
              )}
            </div>
          ))}

          {isTyping && (
            <div className="flex justify-start items-center animate-fade-in">
              <div className="w-8 h-8 rounded-full bg-indigo-100 flex items-center justify-center mr-2">
                 <svg className="w-5 h-5 text-indigo-600" fill="currentColor" viewBox="0 0 20 20"><path d="M10 2a8 8 0 100 16 8 8 0 000-16zm0 14a6 6 0 110-12 6 6 0 010 12z"/></svg>
              </div>
              <div className="bg-white border border-gray-100 rounded-2xl rounded-bl-none p-4 shadow-sm">
                <div className="flex space-x-1.5">
                  <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce"></div>
                  <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '0.15s' }}></div>
                  <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '0.3s' }}></div>
                </div>
              </div>
            </div>
          )}
          <div ref={messagesEndRef} />
        </div>
      </div>

      {/* Input Area */}
      <div className="bg-white border-t border-gray-200 p-4 pb-6">
        <div className="max-w-3xl mx-auto">
          {selectedImage && (
            <div className="mb-3 flex items-center bg-gray-100 px-3 py-2 rounded-lg w-fit animate-slide-up">
              <span className="text-xs font-medium text-gray-600 mr-2">Image attached</span>
              <button 
                onClick={() => setSelectedImage(undefined)}
                className="text-gray-400 hover:text-red-500"
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 20 20" fill="currentColor">
                  <path fillRule="evenodd" d="M4.293 4.293a1 1 0 011.414 0L10 8.586l4.293-4.293a1 1 0 111.414 1.414L11.414 10l4.293 4.293a1 1 0 01-1.414 1.414L10 11.414l-4.293 4.293a1 1 0 01-1.414-1.414L8.586 10 4.293 5.707a1 1 0 010-1.414z" clipRule="evenodd" />
                </svg>
              </button>
            </div>
          )}

          <form onSubmit={handleSubmit} className="relative flex items-end space-x-3">
            <div className="flex-1 bg-gray-50 border border-gray-200 rounded-2xl focus-within:ring-2 focus-within:ring-primary focus-within:border-transparent focus-within:bg-white transition-all flex items-end">
               <input 
                  type="file" 
                  ref={fileInputRef}
                  className="hidden"
                  accept="image/*"
                  onChange={handleImageUpload}
               />
               <button 
                type="button"
                onClick={() => fileInputRef.current?.click()}
                className="p-3 text-gray-400 hover:text-primary transition-colors h-12"
                title="Attach image"
               >
                 <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
                  </svg>
               </button>
               <textarea
                ref={textareaRef}
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={handleKeyDown}
                onPaste={handlePaste}
                placeholder={appState === AppState.INIT ? "E.g., How does gravity work? (You can paste images here)" : "Type your message..."}
                className="w-full py-3 bg-transparent border-none focus:ring-0 text-gray-800 placeholder-gray-400 resize-none max-h-40 min-h-[48px]"
                disabled={isTyping}
                rows={1}
              />
            </div>
            <button
              type="submit"
              disabled={(!input.trim() && !selectedImage) || isTyping}
              className="p-3 rounded-xl bg-primary text-white shadow-lg hover:bg-indigo-700 disabled:opacity-50 disabled:shadow-none transition-all duration-200 h-12 w-12 flex items-center justify-center"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 transform rotate-90" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" />
              </svg>
            </button>
          </form>
          <div className="text-center mt-2 text-xs text-gray-400">
            Shift + Enter for new line • Drag & Drop images
          </div>
        </div>
      </div>
    </div>
  );
};

export default ChatView;
